/* PortalFlow commerce: browser-local records, manual payment status and acknowledgement. */
(function (PF) {
  'use strict';
  const currencies = ['INR','USD','EUR','GBP'];
  const statuses = ['draft','issued','paid'];
  const E = PF.e;
  const opts = values => values.map(v=>[v,v[0].toUpperCase()+v.slice(1)]);
  function fail(message) { throw new Error(message); }
  function text(value,label,max=12000) { if(typeof value!=='string'||!value.trim()||value.length>max) fail(label+' is required and must be within '+max+' characters.'); return value.trim(); }
  function num(value,label) { if((typeof value!=='number'&&typeof value!=='string')||String(value).trim()==='') fail(label+' must be a nonnegative number.'); const n=Number(value); if(!Number.isFinite(n)||n<0) fail(label+' must be a finite nonnegative number.'); return n; }
  function savedNum(value,label) { if(typeof value!=='number') fail(label+' must be numeric.'); return num(value,label); }
  function one(value,values,label) { if(!values.includes(value)) fail('Invalid '+label+'.'); return value; }
  function date(value,label,optional=false) { if(optional&&value==='')return value; if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value+'T00:00:00Z'))||new Date(value+'T00:00:00Z').toISOString().slice(0,10)!==value)fail('Invalid '+label+'.'); return value; }
  function instant(value) { if(typeof value!=='string'||!Number.isFinite(Date.parse(value)))fail('Invalid timestamp.'); }
  function project(id) { if(!PF.db.projects.some(p=>p.id===id))fail('Choose an existing project.'); return id; }
  function client(id) { if(!PF.db.clients.some(c=>c.id===id))fail('Choose an existing client.'); return id; }
  function url(value) { if(value==='')return ''; try { const u=new URL(value); if(!['https:','http:'].includes(u.protocol)||u.username||u.password)fail('Use a public HTTP or HTTPS payment link.'); return u.href; } catch (_) { fail('Use a valid HTTP or HTTPS payment link.'); } }
  function record(table,id) { const found=PF.w[table].find(r=>r.id===id); if(!found)fail('This record no longer exists.'); return found; }
  function totals(invoice) { const subtotal=invoice.items.reduce((s,i)=>s+i.quantity*i.rate,0); const tax=subtotal*invoice.taxPercent/100; if(![subtotal,tax,subtotal+tax].every(Number.isFinite))fail('Invoice total is too large.'); return {subtotal,tax,total:subtotal+tax}; }
  const money=(n,c)=>E(PF.money(n,c));
  const projectName=id=>PF.project(id)?.name||'Unknown project';
  const clientName=id=>PF.client(id)?.name||'Unknown client';
  const row=(body,actions='')=>'<div class="row"><div>'+body+'</div><div class="actions">'+actions+'</div></div>';
  function parseItems(raw) { return text(raw,'Line items').split(/\r?\n/).filter(v=>v.trim()).map(line=>{const parts=line.split('|');if(parts.length!==3)fail('Each line must use description | quantity | rate.');return {description:text(parts[0],'Description',500),quantity:num(parts[1],'Quantity'),rate:num(parts[2],'Rate')};}); }
  const numeric=(name,label,value)=>'<label>'+E(label)+'<input type="number" name="'+name+'" min="0" step="any" required value="'+E(value)+'"></label>';
  function invoiceForm(id='',projectId='') {
    const existing=id?record('invoices',id):null;
    PF.form(id?'Edit invoice':'New invoice',PF.select('projectId','Project',PF.projectOptions(),existing?.projectId||projectId)+PF.field('number','Invoice number','text',existing?.number||'')+PF.select('currency','Currency',opts(currencies),existing?.currency||'USD')+PF.area('items','Line items — one per line: description | quantity | rate',true,existing?existing.items.map(i=>[i.description,i.quantity,i.rate].join(' | ')).join('\n'):'Design work | 1 | 100')+numeric('taxPercent','Tax %',existing?.taxPercent??0)+PF.select('status','Manual status',opts(statuses),existing?.status||'draft')+PF.field('due','Due date','date',existing?.due||'',false)+PF.field('paymentUrl','Optional external payment link (not processed here)','url',existing?.paymentUrl||'',false),values=>{
      const next={projectId:project(values.projectId),number:text(values.number,'Invoice number',100),currency:one(values.currency,currencies,'currency'),items:parseItems(values.items),taxPercent:num(values.taxPercent,'Tax'),status:one(values.status,statuses,'status'),due:date(values.due,'due date',true),paymentUrl:url(values.paymentUrl.trim())};
      if(PF.w.invoices.some(i=>i.id!==id&&i.number.trim().toLowerCase()===next.number.toLowerCase()))fail('Invoice number already exists.');
      totals(next);
      if(id)Object.assign(record('invoices',id),next);else PF.w.invoices.push({...next,id:PF.id(),createdAt:PF.now()});
      PF.log('invoice','Saved invoice '+next.number,next.projectId);
    });
  }
  function invoiceRows(invoices) { return invoices.map(i=>row('<h3>'+E(i.number)+' · '+money(totals(i).total,i.currency)+'</h3><p>'+E(projectName(i.projectId))+' · '+E(i.status)+' · '+(i.due?'Due '+E(PF.date(i.due)):'No due date')+'</p><div class="meta">'+i.items.length+' line item(s) · status set manually</div>',PF.button('Edit','pf-edit-invoice',i.id)+PF.button('CSV','pf-invoice-csv',i.id)+PF.button('Print','pf-print-invoice',i.id)+(i.paymentUrl?'<a href="'+E(url(i.paymentUrl))+'" target="_blank" rel="noopener noreferrer">External payment link ↗</a>':''))).join('')||PF.empty('No invoices yet.'); }
  function summary(invoices=PF.w.invoices) { const out={}; invoices.forEach(i=>{const group=out[i.currency]||(out[i.currency]={draft:0,issued:0,paid:0,total:0});const amount=totals(i).total;group[i.status]+=amount;group.total+=amount;if(!Number.isFinite(group.total))fail('Combined total is too large.');});return out; }
  PF.commerceSummary=summary;
  PF.views.billing={title:'Billing',icon:'＄',group:'work',render(){const sums=summary();return PF.heading('Billing','Local invoices. Issued and paid statuses are set manually.',PF.button('New invoice','pf-add-invoice','',true))+'<div class="stats">'+Object.entries(sums).map(([c,v])=>'<div class="card stat"><small>'+E(c)+' · issued / unpaid</small><strong>'+money(v.issued,c)+'</strong><small>Paid '+money(v.paid,c)+' · Draft '+money(v.draft,c)+'</small></div>').join('')+'</div><section class="card">'+invoiceRows(PF.w.invoices)+'</section>';}};
  PF.actions['pf-add-invoice']=b=>invoiceForm('',b.dataset.id||'');
  PF.actions['pf-edit-invoice']=b=>invoiceForm(b.dataset.id);
  function csv(value) { if(PF.csvCell)return PF.csvCell(value);let s=String(value??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'; }
  PF.actions['pf-invoice-csv']=b=>{const i=record('invoices',b.dataset.id),t=totals(i);const rows=[['Invoice',i.number],['Project',projectName(i.projectId)],['Currency',i.currency],['Manual status',i.status],['Due',i.due],[],['Description','Quantity','Rate','Line total'],...i.items.map(x=>[x.description,x.quantity,x.rate,x.quantity*x.rate]),[],['Subtotal',t.subtotal],['Tax %',i.taxPercent],['Tax',t.tax],['Total ('+i.currency+')',t.total]];PF.download('invoice.csv',rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8');};
  PF.actions['pf-print-invoice']=b=>{const i=record('invoices',b.dataset.id),t=totals(i);const win=window.open('','_blank');if(!win)fail('Allow a new window to print this invoice.');win.opener=null;win.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Invoice '+E(i.number)+'</title><style>body{font:16px system-ui;margin:45px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #ddd}</style></head><body><h1>Invoice '+E(i.number)+'</h1><p>'+E(projectName(i.projectId))+' · '+E(i.currency)+' · '+E(i.status)+' (manual)</p><p>Due: '+E(i.due||'Not set')+'</p><table><thead><tr><th>Description</th><th>Quantity</th><th>Rate</th><th>Amount</th></tr></thead><tbody>'+i.items.map(x=>'<tr><td>'+E(x.description)+'</td><td>'+E(x.quantity)+'</td><td>'+money(x.rate,i.currency)+'</td><td>'+money(x.quantity*x.rate,i.currency)+'</td></tr>').join('')+'</tbody></table><p>Subtotal: '+money(t.subtotal,i.currency)+'</p><p>Tax ('+E(i.taxPercent)+'%): '+money(t.tax,i.currency)+'</p><h2>Total: '+money(t.total,i.currency)+'</h2><p>Browser-local demo. Payment is not processed here.</p></body></html>');win.document.close();win.focus();win.print();};
  function timeForm(id='',projectId='') {const old=id?record('timeEntries',id):null;PF.form(id?'Edit time entry':'Log time',PF.select('projectId','Project',PF.projectOptions(),old?.projectId||projectId)+PF.field('description','Description','text',old?.description||'')+numeric('minutes','Minutes',old?.minutes??30)+PF.select('billable','Billable',[['yes','Yes'],['no','No']],old?.billable===false?'no':'yes')+PF.field('date','Work date','date',old?.date||PF.now().slice(0,10))+numeric('rate','Reference hourly rate (project currency; not invoiced)',old?.rate??0),v=>{const next={projectId:project(v.projectId),description:text(v.description,'Description',1000),minutes:num(v.minutes,'Minutes'),billable:one(v.billable,['yes','no'],'billable')==='yes',date:date(v.date,'work date'),rate:num(v.rate,'Rate')};if(id)Object.assign(record('timeEntries',id),next);else PF.w.timeEntries.push({...next,id:PF.id()});PF.log('time','Logged time',next.projectId);});}
  PF.views.time={title:'Time',icon:'◷',group:'work',render(){const timer=PF.w.timer;return PF.heading('Time','Manual entries and one browser-local timer. Rates are references; no currency totals are combined.',PF.button('Log time','pf-add-time','',true))+'<section class="card"><h2>Timer</h2>'+(timer?'<p>'+E(timer.description)+' · '+E(projectName(timer.projectId))+' · started '+E(PF.date(timer.startedAt))+'</p>'+PF.button('Stop and save time','pf-stop-timer',timer.id):'<p>The timer continues across reloads using its saved start time.</p>'+PF.button('Start timer','pf-start-timer'))+'</section><section class="card">'+(PF.w.timeEntries.map(t=>row('<h3>'+E(t.description)+'</h3><p>'+E(projectName(t.projectId))+' · '+E(t.minutes.toFixed(2))+' min · '+E(t.date)+' · '+(t.billable?'Billable':'Non-billable')+'</p>',PF.button('Edit','pf-edit-time',t.id))).join('')||PF.empty('No time entries yet.'))+'</section>';}};
  PF.actions['pf-add-time']=b=>timeForm('',b.dataset.id||'');PF.actions['pf-edit-time']=b=>timeForm(b.dataset.id);
  PF.actions['pf-start-timer']=b=>{if(PF.w.timer)fail('Stop the current timer first.');PF.form('Start timer',PF.select('projectId','Project',PF.projectOptions(),b.dataset.id||'')+PF.field('description','What are you working on?'),v=>{if(PF.w.timer)fail('A timer is already running.');PF.w.timer={id:PF.id(),projectId:project(v.projectId),description:text(v.description,'Description',1000),startedAt:PF.now()};PF.log('time','Started timer',v.projectId);});};
  PF.actions['pf-stop-timer']=b=>PF.change(()=>{const timer=PF.w.timer;if(!timer||timer.id!==b.dataset.id)fail('This timer is no longer running.');project(timer.projectId);const elapsed=(Date.now()-Date.parse(timer.startedAt))/60000;if(!Number.isFinite(elapsed)||elapsed<0)fail('Timer start is in the future; check the device clock.');PF.w.timeEntries.push({id:PF.id(),projectId:timer.projectId,description:timer.description,minutes:elapsed,billable:true,date:timer.startedAt.slice(0,10),rate:0});PF.w.timer=null;PF.log('time','Stopped timer and saved time',timer.projectId);},'Timer saved as a billable entry; edit to adjust.');
  function serviceForm(id=''){const old=id?record('services',id):null;PF.form(id?'Edit service':'New service',PF.field('name','Service name','text',old?.name||'')+PF.area('description','Description',false,old?.description||'')+numeric('price','Price',old?.price??0)+PF.select('currency','Currency',opts(currencies),old?.currency||'USD'),v=>{const next={name:text(v.name,'Service name',200),description:v.description.trim(),price:num(v.price,'Price'),currency:one(v.currency,currencies,'currency')};if(next.description.length>12000)fail('Description is too long.');if(id)Object.assign(record('services',id),next);else PF.w.services.push({...next,id:PF.id()});PF.log('service','Saved service '+next.name);});}
  PF.views.services={title:'Services',icon:'◇',group:'work',render(){return PF.heading('Service catalog','Local reference prices. Creating a service does not create an order or subscription.',PF.button('New service','pf-add-service','',true))+'<section class="card">'+(PF.w.services.map(s=>row('<h3>'+E(s.name)+' · '+money(s.price,s.currency)+'</h3><p style="white-space:pre-wrap">'+E(s.description)+'</p>',PF.button('Edit','pf-edit-service',s.id))).join('')||PF.empty('No services yet.'))+'</section>';}};
  PF.actions['pf-add-service']=()=>serviceForm();PF.actions['pf-edit-service']=b=>serviceForm(b.dataset.id);
  function documentForm(id='',clientId=''){const old=id?record('documents',id):null;PF.form(id?'Edit document':'New document',PF.select('clientId','Client',PF.clientOptions(),old?.clientId||clientId)+PF.field('title','Title','text',old?.title||'')+PF.select('kind','Document type',opts(['proposal','agreement']),old?.kind||'proposal')+PF.area('body','Document text',true,old?.body||'')+'<p>Saving changes returns this document to draft. Acknowledgement is local and is not a legal e-signature.</p>',v=>{const next={clientId:client(v.clientId),title:text(v.title,'Title',300),kind:one(v.kind,['proposal','agreement'],'document type'),body:text(v.body,'Document text'),status:'draft'};if(id)Object.assign(record('documents',id),next);else PF.w.documents.push({...next,id:PF.id(),createdAt:PF.now()});PF.log('document','Saved '+next.kind+' draft','',next.clientId);});}
  function documentRows(documents){return documents.map(d=>row('<h3>'+E(d.title)+'</h3><p>'+E(clientName(d.clientId))+' · '+E(d.kind)+' · '+E(d.status)+'</p><details><summary>Read document</summary><div style="white-space:pre-wrap">'+E(d.body)+'</div></details>',PF.button('Edit','pf-edit-document',d.id)+(d.status==='draft'?PF.button('Acknowledge locally','pf-ack-document',d.id):'<span class="badge">Acknowledged locally</span>'))).join('')||PF.empty('No documents yet.');}
  PF.views.documents={title:'Documents',icon:'▤',group:'work',render(){return PF.heading('Proposals & agreements','Local drafts and client acknowledgement simulation. No legal e-signature or delivery.',PF.button('New document','pf-add-document','',true))+'<section class="card">'+documentRows(PF.w.documents)+'</section>';}};
  PF.actions['pf-add-document']=b=>documentForm('',b.dataset.id||'');PF.actions['pf-edit-document']=b=>documentForm(b.dataset.id);
  PF.actions['pf-ack-document']=b=>{const id=b.dataset.id,old=record('documents',id),snapshot=JSON.stringify(old);PF.form('Local acknowledgement','<p>Client preview: acknowledge “'+E(old.title)+'” for '+E(clientName(old.clientId))+'. This records a local demo status only; it is not a legal e-signature.</p>'+PF.select('ack','Explicit acknowledgement',[['','Choose…'],['yes','I acknowledge this document locally']]),v=>{if(v.ack!=='yes')fail('Choose the explicit acknowledgement.');const current=record('documents',id);if(JSON.stringify(current)!==snapshot)fail('Document changed; read it again before acknowledging.');client(current.clientId);current.status='acknowledged';PF.log('document','Document acknowledged locally: '+current.title,'',current.clientId);});};
  PF.projectSections.push(p=>'<section class="card"><h2>Project invoices</h2>'+PF.button('New invoice','pf-add-invoice',p.id)+invoiceRows(PF.w.invoices.filter(i=>i.projectId===p.id))+'<div class="actions">'+PF.button('Log project time','pf-add-time',p.id)+(!PF.w.timer?PF.button('Start project timer','pf-start-timer',p.id):'')+'</div></section>');
  PF.clientSections.push(c=>{const ids=new Set(PF.db.projects.filter(p=>p.clientId===c.id).map(p=>p.id));return '<section class="card"><h2>Client invoices</h2>'+invoiceRows(PF.w.invoices.filter(i=>ids.has(i.projectId)))+'</section><section class="card"><h2>Proposals & agreements</h2><p>Local client preview acknowledgement only; no legal e-signature.</p>'+PF.button('New client document','pf-add-document',c.id)+documentRows(PF.w.documents.filter(d=>d.clientId===c.id))+'</section>';});
  PF.validators.push((w,data)=>{
    const projectIds=new Set(data.projects.map(p=>p.id)),clientIds=new Set(data.clients.map(c=>c.id));
    const fk=(id,set,label)=>{if(!set.has(id))fail('Invalid '+label+' reference.');};
    ['invoices','timeEntries','services','documents'].forEach(table=>{if(!Array.isArray(w[table]))fail('Invalid '+table+'.');const ids=new Set();w[table].forEach(r=>{if(!r||typeof r!=='object'||typeof r.id!=='string'||!r.id||ids.has(r.id))fail('Invalid or duplicate '+table+' ID.');ids.add(r.id);});});
    const numbers=new Set();w.invoices.forEach(i=>{fk(i.projectId,projectIds,'invoice project');const n=text(i.number,'Invoice number',100).toLowerCase();if(numbers.has(n))fail('Duplicate invoice number.');numbers.add(n);one(i.currency,currencies,'currency');one(i.status,statuses,'invoice status');date(i.due,'due date',true);url(i.paymentUrl);instant(i.createdAt);savedNum(i.taxPercent,'Tax');if(!Array.isArray(i.items)||!i.items.length)fail('Invoice needs line items.');i.items.forEach(item=>{text(item.description,'Description',500);savedNum(item.quantity,'Quantity');savedNum(item.rate,'Rate');});totals(i);});
    summary(w.invoices);
    w.timeEntries.forEach(t=>{fk(t.projectId,projectIds,'time project');text(t.description,'Description',1000);savedNum(t.minutes,'Minutes');savedNum(t.rate,'Rate');if(typeof t.billable!=='boolean')fail('Invalid billable value.');date(t.date,'work date');});
    w.services.forEach(s=>{text(s.name,'Service name',200);if(typeof s.description!=='string'||s.description.length>12000)fail('Invalid service description.');savedNum(s.price,'Price');one(s.currency,currencies,'currency');});
    w.documents.forEach(d=>{fk(d.clientId,clientIds,'document client');text(d.title,'Title',300);text(d.body,'Document text');one(d.kind,['proposal','agreement'],'document type');one(d.status,['draft','acknowledged'],'document status');instant(d.createdAt);});
    if(w.timer!==null){const t=w.timer;if(!t||typeof t!=='object')fail('Invalid timer.');text(t.id,'Timer ID',200);fk(t.projectId,projectIds,'timer project');text(t.description,'Timer description',1000);instant(t.startedAt);}
  });
})(window.PF);
